export interface ContactValues {
  name: string
  email: string
  message: string
}

export type ContactErrors = Partial<Record<keyof ContactValues, string>>

export const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

export function normalizeContact(input: unknown): ContactValues {
  const source = (input && typeof input === 'object' ? input : {}) as Record<string, unknown>
  const field = (key: keyof ContactValues) => (typeof source[key] === 'string' ? source[key] : '')
  return { name: field('name'), email: field('email'), message: field('message') }
}

export function validateContact(values: ContactValues): ContactErrors {
  const name = values.name.trim()
  const email = values.email.trim()
  const message = values.message.trim()
  const errors: ContactErrors = {}

  if (!name) errors.name = 'Name is required.'
  if (!email) errors.email = 'Email is required.'
  else if (!EMAIL_PATTERN.test(email)) errors.email = 'Enter a valid email address.'
  if (message.length < 20) errors.message = 'Message must be at least 20 characters.'

  return errors
}

export function successMessage(name: string) {
  return `Thanks, ${name.trim()}! Your message has been sent.`
}

export interface ContactResult {
  values: ContactValues
  errors: ContactErrors
  success: string | null
}

export function handleContact(input: unknown): ContactResult {
  const values = normalizeContact(input)
  const errors = validateContact(values)
  const ok = Object.keys(errors).length === 0
  return {
    values: ok ? { name: '', email: '', message: '' } : values,
    errors,
    success: ok ? successMessage(values.name) : null
  }
}
