// is left on the event context and the /contact page renders it.
export default defineEventHandler(async (event) => {
  if (event.method !== 'POST' || getRequestURL(event).pathname.replace(/\/$/, '') !== '/contact') {
    return
  }
  const body = await readBody(event).catch(() => ({}))
  event.context.contact = handleContact(body)
})
