<script setup lang="ts">
useHead({ title: 'Contact' })

// Result of a form posted without JavaScript (see server/middleware/contact.ts)
const posted = useState<ContactResult | null>('contact-posted', () => useRequestEvent()?.context.contact ?? null)

const values = reactive<ContactValues>({ ...(posted.value?.values ?? { name: '', email: '', message: '' }) })
const errors = ref<ContactErrors>(posted.value?.errors ?? {})
const success = ref<string | null>(posted.value?.success ?? null)
const sending = ref(false)

async function onSubmit() {
  success.value = null
  errors.value = validateContact(values)
  if (Object.keys(errors.value).length > 0) return

  sending.value = true
  try {
    const result = await $fetch<ContactResult>('/api/contact', {
      method: 'POST',
      body: { ...values },
      ignoreResponseError: true
    })
    errors.value = result.errors
    success.value = result.success
    if (result.success) Object.assign(values, result.values)
  }
  finally {
    sending.value = false
  }
}
</script>

<template>
  <div>
    <h1>Contact</h1>

    <p v-if="success" role="status" class="success">{{ success }}</p>

    <form method="post" action="/contact" novalidate @submit.prevent="onSubmit">
      <div class="field">
        <label for="contact-name">Name</label>
        <input
          id="contact-name"
          v-model="values.name"
          type="text"
          name="name"
          autocomplete="name"
          :aria-invalid="errors.name ? 'true' : undefined"
          :aria-describedby="errors.name ? 'contact-name-error' : undefined"
        >
        <p v-if="errors.name" id="contact-name-error" class="error">{{ errors.name }}</p>
      </div>

      <div class="field">
        <label for="contact-email">Email</label>
        <input
          id="contact-email"
          v-model="values.email"
          type="email"
          name="email"
          autocomplete="email"
          :aria-invalid="errors.email ? 'true' : undefined"
          :aria-describedby="errors.email ? 'contact-email-error' : undefined"
        >
        <p v-if="errors.email" id="contact-email-error" class="error">{{ errors.email }}</p>
      </div>

      <div class="field">
        <label for="contact-message">Message</label>
        <textarea
          id="contact-message"
          v-model="values.message"
          name="message"
          rows="6"
          :aria-invalid="errors.message ? 'true' : undefined"
          :aria-describedby="errors.message ? 'contact-message-error' : undefined"
        />
        <p v-if="errors.message" id="contact-message-error" class="error">{{ errors.message }}</p>
      </div>

      <button type="submit" :disabled="sending">Send</button>
    </form>
  </div>
</template>

<style scoped>
.field {
  display: flex;
  flex-direction: column;
  margin-bottom: 1rem;
}
.field input,
.field textarea {
  font: inherit;
  padding: 0.25rem;
}
.success {
  color: #1b5e20;
  font-weight: bold;
}
</style>
EOF
